mkuse!{use std :: cmp :: Ordering ;}
mkuse!{use std :: hash :: { Hash , Hasher } ;}
mkuse!{use std :: ops :: Deref ;}
mkuse!{# [cfg (feature = "nightly")] use rustc_data_structures :: fingerprint :: Fingerprint ;}
mkuse!{# [cfg (feature = "nightly")] use rustc_data_structures :: stable_hasher :: { HashStable , StableHasher } ;}
mkuse!{use crate :: { DebruijnIndex , TypeFlags } ;}
mkitem!{mkstruct!{# [doc = " A helper type that you can wrap round your own type in order to automatically"] # [doc = " cache the stable hash, type flags and debruijn index on creation and"] # [doc = " not recompute it whenever the information is needed."] # [doc = " This is only done in incremental mode. You can also opt out of caching by using"] # [doc = " StableHash::ZERO for the hash, in which case the hash gets computed each time."] # [doc = " This is useful if you have values that you intern but never (can?) use for stable"] # [doc = " hashing."] # [derive (Copy , Clone)] pub struct WithCachedTypeInfo < T > { pub internee : T , # [cfg (feature = "nightly")] pub stable_hash : Fingerprint , # [doc = " This field provides fast access to information that is also contained"] # [doc = " in `kind`."] # [doc = ""] # [doc = " This field shouldn't be used directly and may be removed in the future."] # [doc = " Use `Ty::flags()` instead."] pub flags : TypeFlags , # [doc = " This field provides fast access to information that is also contained"] # [doc = " in `kind`."] # [doc = ""] # [doc = " This is a kind of confusing thing: it stores the smallest"] # [doc = " binder such that"] # [doc = ""] # [doc = " (a) the binder itself captures nothing but"] # [doc = " (b) all the late-bound things within the type are captured"] # [doc = "     by some sub-binder."] # [doc = ""] # [doc = " So, for a type without any late-bound things, like `u32`, this"] # [doc = " will be *innermost*, because that is the innermost binder that"] # [doc = " captures nothing. But for a type `&'D u32`, where `'D` is a"] # [doc = " late-bound region with De Bruijn index `D`, this would be `D + 1`"] # [doc = " -- the binder itself does not capture `D`, but `D` is captured"] # [doc = " by an inner binder."] # [doc = ""] # [doc = " We call this concept an \"exclusive\" binder `D` because all"] # [doc = " De Bruijn indices within the type are contained within `0..D`"] # [doc = " (exclusive)."] pub outer_exclusive_binder : DebruijnIndex , }}}
mkitem!{mkimpl!{impl < T : PartialEq > PartialEq for WithCachedTypeInfo < T > { # [inline] fn eq (& self , other : & Self) -> bool { self . internee . eq (& other . internee) } }}}
mkitem!{mkimpl!{impl < T : Eq > Eq for WithCachedTypeInfo < T > { }}}
mkitem!{mkimpl!{impl < T : Ord > PartialOrd for WithCachedTypeInfo < T > { fn partial_cmp (& self , other : & WithCachedTypeInfo < T >) -> Option < Ordering > { Some (self . internee . cmp (& other . internee)) } }}}
mkitem!{mkimpl!{impl < T : Ord > Ord for WithCachedTypeInfo < T > { fn cmp (& self , other : & WithCachedTypeInfo < T >) -> Ordering { self . internee . cmp (& other . internee) } }}}
mkitem!{mkimpl!{impl < T > Deref for WithCachedTypeInfo < T > { type Target = T ; # [inline] fn deref (& self) -> & T { & self . internee } }}}
mkitem!{mkimpl!{impl < T : Hash > Hash for WithCachedTypeInfo < T > { # [inline] fn hash < H : Hasher > (& self , s : & mut H) { # [cfg (feature = "nightly")] if self . stable_hash != Fingerprint :: ZERO { return self . stable_hash . hash (s) ; } self . internee . hash (s) } }}}
mkitem!{mkimpl!{# [cfg (feature = "nightly")] impl < T : HashStable < CTX > , CTX > HashStable < CTX > for WithCachedTypeInfo < T > { fn hash_stable (& self , hcx : & mut CTX , hasher : & mut StableHasher) { if self . stable_hash == Fingerprint :: ZERO || cfg ! (debug_assertions) { let stable_hash : Fingerprint = { let mut hasher = StableHasher :: new () ; self . internee . hash_stable (hcx , & mut hasher) ; hasher . finish () } ; if cfg ! (debug_assertions) && self . stable_hash != Fingerprint :: ZERO { assert_eq ! (stable_hash , self . stable_hash , "cached stable hash does not match freshly computed stable hash") ; } stable_hash . hash_stable (hcx , hasher) ; } else { self . stable_hash . hash_stable (hcx , hasher) ; } } }}}